  if [ -z "$srcfile" ]; then echo "MISS $name (frag '$frag')"; continue; fi
  echo "== $name <- $(basename "$srcfile")"
  "$KPY" "$PREP" "$srcfile" "$STRESS/boards_set33/$name.kicad_pcb" \
         "$STRESS/boards_unrouted_set33/$name.kicad_pcb" 2>/dev/null || echo "  FAIL $name"
  profile="${srcfile%.kicad_pcb}.kicad_pro"
  [ -f "$profile" ] && cp "$profile" "$STRESS/boards_set33/$name.kicad_pro"
done
echo "Done. stripped -> boards_unrouted_set33/ ; routed reference -> boards_set33/"
